//! l.startswith("? ")]`; never edit those lines by hand.

use mw_check::textcompare::ndiff;

fn lines(items: &[&str]) -> Vec<String> {
    items.iter().map(|s| s.to_string()).collect()
}

struct Case {
    name: &'static str,
    a: &'static [&'static str],
    b: &'static [&'static str],
    expected: &'static [&'static str],
}

